export interface Page {
  slug: string;
  title: string;
  date?: string;
  tags: string[];
  html: string;
  template?: string;
  layout?: string;
}

import matter from 'gray-matter';

export interface Frontmatter {
  title: string;
  date?: string;
  tags: string[];
  template?: string;
  layout?: string;
}

export interface ParsedDocument {
  frontmatter: Frontmatter;
  content: string;
}

// gray-matter requires the opening `---` to be the very first bytes of the
// file, so we extract the block manually (allowing an optional BOM) and hand
// only the raw frontmatter to gray-matter for YAML parsing.
const FRONTMATTER_RE = /^\uFEFF?---[ \t]*\r?\n([\s\S]*?)\r?\n---[ \t]*(?:\r?\n|$)/;

function dateToString(value: unknown): string | undefined {
  if (typeof value === 'string') {
    return value;
  }
  if (value instanceof Date && !Number.isNaN(value.getTime())) {
    return value.toISOString().slice(0, 10);
  }
  return undefined;
}

function optionalString(value: unknown): string | undefined {
  if (typeof value === 'string' && value.trim().length > 0) {
    return value.trim();
  }
  return undefined;
}

function normalizeTags(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value
      .filter((v): v is string => typeof v === 'string')
      .map((v) => v.trim())
      .filter((v) => v.length > 0);
  }
  if (typeof value === 'string') {
    return value
      .split(',')
      .map((v) => v.trim())
      .filter((v) => v.length > 0);
  }
  return [];
}

export function extractFrontmatter(source: string): ParsedDocument {
  const match = FRONTMATTER_RE.exec(source);
  if (!match) {
    return { frontmatter: { title: '', tags: [] }, content: source };
  }

  const parsed = matter(match[0]);
  const raw = parsed.data as Record<string, unknown>;

  return {
    frontmatter: {
      title: typeof raw.title === 'string' ? raw.title : '',
      date: dateToString(raw.date),
      tags: normalizeTags(raw.tags),
      template: optionalString(raw.template),
      layout: optionalString(raw.layout),
    },
    content: source.slice(match[0].length),
  };
}

import { promises as fs } from 'fs';
import path from 'path';
import Handlebars from 'handlebars';
import type { Page } from './types';

const STYLE = [
  'body { font-family: system-ui, -apple-system, sans-serif; max-width: 48rem; margin: 0 auto; padding: 1.5rem; line-height: 1.6; color: #1a1a1a; }',
  'header { margin-bottom: 2rem; }',
  'a { color: #0b5fff; text-decoration: none; }',
  'a:hover { text-decoration: underline; }',
  '.meta { display: flex; gap: 1rem; align-items: center; color: #666; font-size: 0.9rem; margin-bottom: 1.5rem; }',
  '.tags { display: flex; gap: 0.5rem; }',
  '.tag { background: #eef2ff; color: #3b4fd8; padding: 0.15rem 0.5rem; border-radius: 999px; font-size: 0.8rem; }',
  '.content h1 { font-size: 1.6rem; }',
].join('\n');

const BUILTIN_LAYOUT = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{{title}}</title>
<style>
${STYLE}
</style>
</head>
<body>
<header><a href="index.html">&larr; Home</a></header>
<main>
{{{body}}}
</main>
</body>
</html>
`;

const BUILTIN_PAGE_TEMPLATE = `<article>
<h1>{{title}}</h1>
{{#if date}}<div class="meta"><time datetime="{{date}}">{{date}}</time>{{#if tags.length}}<div class="tags">{{#each tags}}<span class="tag">{{this}}</span>{{/each}}</div>{{/if}}</div>{{/if}}
{{#if tags.length}}{{#unless date}}<div class="meta"><div class="tags">{{#each tags}}<span class="tag">{{this}}</span>{{/each}}</div></div>{{/unless}}{{/if}}
<div class="content">
{{{content}}}
</div>
</article>
`;

const BUILTIN_INDEX_TEMPLATE = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Index</title>
<style>
${STYLE}
</style>
</head>
<body>
<header><h1>Index</h1></header>
<main>
<ul>
{{#each pages}}
<li><a href="{{slug}}.html">{{title}}</a>{{#if date}} <time>{{date}}</time>{{/if}}{{#if tags.length}}<div class="tags">{{#each tags}}<span class="tag">{{this}}</span>{{/each}}</div>{{/if}}</li>
{{/each}}
</ul>
</main>
</body>
</html>
`;

export interface PageContext {
  title: string;
  date?: string;
  tags: string[];
  slug: string;
  content: string;
  body: string;
  [key: string]: unknown;
}

export interface TemplateEngine {
  renderPage(page: Page): string;
  renderIndex(pages: Page[]): string;
}

function toContext(page: Page): PageContext {
  return {
    title: page.title,
    date: page.date,
    tags: page.tags,
    slug: page.slug,
    content: page.html,
    body: page.html,
  };
}

async function listTemplateFiles(dir: string): Promise<string[]> {
  try {
    const entries = await fs.readdir(dir, { withFileTypes: true });
    return entries
      .filter((e) => e.isFile() && e.name.toLowerCase().endsWith('.hbs'))
      .map((e) => path.join(dir, e.name));
  } catch {
    return [];
  }
}

async function loadTemplates(
  hbs: typeof Handlebars,
  dir: string
): Promise<Map<string, Handlebars.TemplateDelegate>> {
  const map = new Map<string, Handlebars.TemplateDelegate>();
  for (const file of await listTemplateFiles(dir)) {
    const name = path.basename(file, path.extname(file));
    const source = await fs.readFile(file, 'utf8');
    map.set(name, hbs.compile(source));
  }
  return map;
}

export async function createTemplateEngine(
  templatesDir: string
): Promise<TemplateEngine> {
  const hbs = Handlebars.create();

  const partialsDir = path.join(templatesDir, 'partials');
  for (const file of await listTemplateFiles(partialsDir)) {
    const name = path.basename(file, path.extname(file));
    const source = await fs.readFile(file, 'utf8');
    hbs.registerPartial(name, hbs.compile(source));
  }

  const layouts = await loadTemplates(hbs, path.join(templatesDir, 'layouts'));
  const pageTemplates = await loadTemplates(hbs, templatesDir);

  let indexTemplate: Handlebars.TemplateDelegate | undefined;
  try {
    const source = await fs.readFile(path.join(templatesDir, 'index.hbs'), 'utf8');
    indexTemplate = hbs.compile(source);
  } catch {
    indexTemplate = undefined;
  }

  const defaultLayout = hbs.compile(BUILTIN_LAYOUT);
  const defaultPageTemplate = hbs.compile(BUILTIN_PAGE_TEMPLATE);
  const defaultIndexTemplate = hbs.compile(BUILTIN_INDEX_TEMPLATE);

  return {
    renderPage(page: Page): string {
      const context = toContext(page);
      const templateName = page.template ?? 'default';
      const layoutName = page.layout ?? 'default';

      const pageTemplate = pageTemplates.get(templateName) ?? defaultPageTemplate;
      const body = pageTemplate({ ...context });

      const layout = layouts.get(layoutName) ?? defaultLayout;
      return layout({ ...context, body });
    },
    renderIndex(pages: Page[]): string {
      const template = indexTemplate ?? defaultIndexTemplate;
      return template({ pages });
    },
  };
}

import { promises as fs } from 'fs';
import path from 'path';
import { extractFrontmatter } from './frontmatter';
import { renderMarkdown } from './markdown';
import { createTemplateEngine } from './engine';
import type { Page } from './types';

export interface BuildResult {
  pages: Page[];
  outputDir: string;
}

export async function listMarkdownFiles(dir: string): Promise<string[]> {
  const out: string[] = [];
  const entries = await fs.readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      out.push(...(await listMarkdownFiles(full)));
    } else if (entry.isFile() && entry.name.toLowerCase().endsWith('.md')) {
      out.push(full);
    }
  }
  return out;
}

function toTitle(slug: string): string {
  const base = path.basename(slug);
  return base
    .replace(/[-_]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

export async function readPage(filePath: string, contentDir: string): Promise<Page> {
  const source = await fs.readFile(filePath, 'utf8');
  const { frontmatter, content } = extractFrontmatter(source);
  const rel = path.relative(contentDir, filePath).split(path.sep).join('/');
  const slug = rel.replace(/\.md$/i, '');
  const title = frontmatter.title || toTitle(slug);
  return {
    slug,
    title,
    date: frontmatter.date,
    tags: frontmatter.tags,
    html: renderMarkdown(content),
    template: frontmatter.template,
    layout: frontmatter.layout,
  };
}

function comparePages(a: Page, b: Page): number {
  const da = a.date ? Date.parse(a.date) : NaN;
  const db = b.date ? Date.parse(b.date) : NaN;
  const daValid = !Number.isNaN(da);
  const dbValid = !Number.isNaN(db);

  if (daValid && dbValid) {
    if (da !== db) {
      return db - da;
    }
  } else if (daValid) {
    return -1;
  } else if (dbValid) {
    return 1;
  }
  return a.title.localeCompare(b.title);
}

export async function buildSite(
  contentDir: string,
  outputDir: string,
  templatesDir = './templates'
): Promise<BuildResult> {
  const files = await listMarkdownFiles(contentDir);

  const pages: Page[] = [];
  for (const file of files) {
    pages.push(await readPage(file, contentDir));
  }
  pages.sort(comparePages);

  const engine = await createTemplateEngine(templatesDir);

  await fs.mkdir(outputDir, { recursive: true });
  await fs.writeFile(path.join(outputDir, 'index.html'), engine.renderIndex(pages), 'utf8');

  for (const page of pages) {
    const outPath = path.join(outputDir, `${page.slug}.html`);
    await fs.mkdir(path.dirname(outPath), { recursive: true });
    await fs.writeFile(outPath, engine.renderPage(page), 'utf8');
  }

  return { pages, outputDir };
}

#!/usr/bin/env node
import { buildSite } from './generate';

export interface CliOptions {
  command: string | null;
  content: string;
  output: string;
  templates: string;
  help: boolean;
}

export function parseArgs(args: string[]): CliOptions {
  const options: CliOptions = {
    command: null,
    content: './content',
    output: './dist',
    templates: './templates',
    help: false,
  };

  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (arg === 'build') {
      options.command = 'build';
    } else if (arg === '--content' || arg === '-c') {
      options.content = args[i + 1] ?? options.content;
      if (args[i + 1] !== undefined) i += 1;
    } else if (arg.startsWith('--content=')) {
      options.content = arg.slice('--content='.length);
    } else if (arg === '--output' || arg === '-o') {
      options.output = args[i + 1] ?? options.output;
      if (args[i + 1] !== undefined) i += 1;
    } else if (arg.startsWith('--output=')) {
      options.output = arg.slice('--output='.length);
    } else if (arg === '--templates' || arg === '-t') {
      options.templates = args[i + 1] ?? options.templates;
      if (args[i + 1] !== undefined) i += 1;
    } else if (arg.startsWith('--templates=')) {
      options.templates = arg.slice('--templates='.length);
    } else if (arg === '--help' || arg === '-h') {
      options.help = true;
    }
  }

  return options;
}

export function printUsage(): string {
  return [
    'Usage: npx ssg build [options]',
    '',
    'Build a static site from Markdown files.',
    '',
    'Options:',
    '  --content <dir>, -c <dir>  Markdown content directory (default: ./content)',
    '  --output <dir>,  -o <dir>  Output directory (default: ./dist)',
    '  --templates <dir>, -t <dir> Template directory (default: ./templates)',
    '  --help, -h                 Show this help message',
  ].join('\n');
}

export async function run(argv: string[]): Promise<void> {
  const options = parseArgs(argv.slice(2));

  if (options.help || options.command !== 'build') {
    process.stdout.write(`${printUsage()}\n`);
    return;
  }

  const result = await buildSite(options.content, options.output, options.templates);
  process.stdout.write(`Built ${result.pages.length} page(s) into ${options.output}\n`);
}

if (require.main === module) {
  run(process.argv).catch((err: unknown) => {
    const message = err instanceof Error ? err.message : String(err);
    process.stderr.write(`${message}\n`);
    process.exitCode = 1;
  });
}

